#include <bitset>
#include <stdexcept>
#include <iostream>

int main() {
    std::bitset<8> flags("10110001");

    // Query Operations
    std::cout << "Size: " << flags.size() << "\n";
    std::cout << "Count (set bits): " << flags.count() << "\n"; // Output: 4
    std::cout << "Any set? " << flags.any() << "\n"; // Output: 1 (true)

    // Test specific bit
    if (flags.test(7)) {
        std::cout << "Bit 7 is set.\n";
    }

    try {
        flags.test(8); // Index 8 is out of range for bitset<8>
    } catch (const std::out_of_range& e) {
        std::cerr << "Error: Index out of range.\n";
    }
}
